220eb42e20b2cd00ee32f00fb17f7f6f44b6e11e612e89103df73","cover_id":10846733,"reference":"cover-semantic-review-002.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"cover_url":"https://covers.openlibrary.org/b/id/10846733-L.jpg?default=false","edition_id":987218005,"bound_title":"Welkom in het Rijk der zieken","reviewed_at":"2026-11-02T21:38:34.662+00:00","bound_isbn13":"9789492928283","evidence_url":"https://data.bibliotheken.nl/id/nbt/p420544577","review_batch":"nl-scale-20261102-019","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/10846733-M.jpg?default=false","bound_author_id":969300004},"before_row":null},{"key":{"native_identity_key":"nlscale:20261102:ol:OL972173W"},"seq":23,"relation":"works","after_row":{"id":987118006,"title":"De kleine blonde dood","cover_id":6275547,"author_id":987318002,"work_type":"novel","source_type":"open_library","open_library_id":"OL972173W","first_publish_year":1985,"native_identity_key":"nlscale:20261102:ol:OL972173W"},"before_row":null},{"key":{"open_library_edition_id":"OL2764862M"},"seq":24,"relation":"editions","after_row":{"id":987218006,"title":"De kleine blonde dood","isbn_10":null,"isbn_13":"9789029508483","work_id":987118006,"cover_id":6275547,"language":"dut","publisher":"Arbeiderspers","publish_date":null,"open_library_edition_id":"OL2764862M"},"before_row":null},{"key":{"work_id":987118006,"language":"nl"},"seq":25,"relation":"catalog_work_descriptions","after_row":{"text":"Een schrijver kijkt terug op twee vader-zoonverhoudingen die zijn leven beheersen. Als kind probeert hij te begrijpen hoe de oorlogservaringen van zijn vader hun gezin hebben gevormd. Later wordt hij zelf geconfronteerd met het verlies van een jonge zoon. Herinneringen aan beide periodes lopen door elkaar en geven de zoektocht naar nabijheid een pijnlijke lading. De roman gebruikt een autobiografisch aandoende vorm, maar maakt van herinnering en verbeelding een eigen literair verhaal.","work_id":987118006,"evidence":[{"note":"1985novel version196pISBN9789029508483, explicitly distinguished from52p1982EenKleineBlondeDood precursor and later expanded217p versions. Publisher calls the work pseudo-autobiographical. Original short text makes no claims that fictional father/son events are verified author biography. Existing identity and dependencies checked separately before addition.","type":"reviewed_identity_and_bibliography","sources":["https://data.bibliotheken.nl/id/nbt/p853231699"],"reference":"new-work-dossier-readings-019.json#335","checked_at":"2026-11-02T21:38:34.662Z"},{"type":"original_substantive_source_review","review":"content-review-014.json","sources":["https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/de-kleine-blonde-dood/","https://www.bibliotheek.nl/catalogus/titel.343581817.html/de-kleine-blonde-dood/","https://www.boekenplatform.nl/de-kleine-blonde-dood-86022","https://www.dbnl.org/tekst/anbe001lexi01_01/lvlw00094.php?q=4","https://data.bibliotheken.nl/id/nbt/p853231699"]},{"type":"explicit_contributor_roles","credits":[],"limitation":"Existing schema has one primary Work author; no synthetic combined-author identity or author merge."},{"type":"cover_front_review","sha256":"06adf9dca41a31640b975c0698c524f940c1e2bcc5ee962366046d0d5bfe14cd","cover_id":6275547,"reference":"cover-semantic-review-010.json","limitation":"Front title/author and source-edition binding; no barcode or exact printing-year claim."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.singeluitgeverijen.nl/de-arbeiderspers/boek/de-kleine-blonde-dood/","reviewed_at":"2026-11-02T21:38:34.662+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-019","review_status":"approved","bound_author_id":987318002},"before_row":null},{"key":{"edition_id":987218006},"seq":26,"relation":"catalog_editio